        {
          "proposicao": "A gestão de saúde ocupacional, incluindo riscos à saúde do trabalhador, é apresentada como um subsistema de gestão que deve conter política, organização, planejamento, definição de padrões, medidas de desempenho, auditoria e revisão.",
          "trechos": [
            "E9746e7089405e7cc:0:700"
          ],
          "condicoes": [
            "Aplicável ao contexto do guia de inspeção offshore sobre COSHH no Reino Unido",
            "Refere-se à estrutura de gestão, não a condutas clínicas ou critérios de aptidão individual"
          ],
          "limites": [
            "Não define exames, periodicidades, limites de exposição nem critérios médicos de aptidão",
            "É fonte estrangeira e não deve ser convertida em requisito brasileiro"
          ]
        },
        {
          "proposicao": "O desempenho requerido do sistema de gestão de saúde ocupacional deve ser determinado considerando código, norma ou guia reconhecido.",
          "trechos": [
            "E9746e7089405e7cc:0:700"
          ],
          "condicoes": [
            "A proposição aparece como critério de confirmação em inspeção",
            "Depende da existência de referência reconhecida aplicável ao sistema avaliado"
          ],
          "limites": [
            "O trecho não identifica qual código ou norma deve prevalecer em cada caso",
            "Não estabelece, por si só, obrigação regulatória brasileira"
          ]
        },
        {
          "proposicao": "Quando houver debate sobre padrões relevantes ou sobre aspectos da gestão COSHH, o guia indica buscar apoio especializado da equipe de higiene industrial.",
          "trechos": [
            "E9746e7089405e7cc:700:1397"
          ],
          "condicoes": [
            "Situações envolvendo consideração de enforcement ou controvérsia sobre padrões",
            "No arranjo institucional do órgão emissor do guia"
          ],
          "limites": [
            "Trata de apoio técnico-inspectivo, não de vigilância médica direta",
            "Não especifica método de monitoramento biológico, ambiental ou clínico"
          ]
        }
      ]
